5	<meta name="viewport" content="width=device-width,initial-scale=1" />
6	<title>Hidroing — Projektiranje i inženjering hidrotehničkih građevina</title>
7	<link rel="preconnect" href="https://fonts.googleapis.com">
8	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
9	<link href="https://fonts.googleapis.com/css2?family=Inter+Tight:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
10	<link rel="stylesheet" href="styles.css" />
11	<style>
12	  /* ---------- Homepage-specific ---------- */
13	  .hero {
14	    padding-top: clamp(60px, 8vw, 120px);
15	    padding-bottom: clamp(40px, 6vw, 80px);
16	  }
17	  .hero__meta {
18	    display: flex;
19	    justify-content: space-between;
20	    align-items: center;
21	    gap: 24px;
22	    margin-bottom: 48px;
23	  }
24	  .hero__meta .meta-line {
25	    font-family: var(--mono);
26	    font-size: 11px;
27	    letter-spacing: 0.08em;
28	    text-transform: uppercase;
29	    color: var(--ink-3);
30	  }
31	  .hero__title {
32	    font-weight: 500;
33	    letter-spacing: -0.035em;
34	    line-height: 0.95;
35	    font-size: clamp(56px, 10vw, 156px);
36	    margin: 0;
37	    text-wrap: balance;
38	  }
39	  .hero__title em {
40	    font-style: normal;
41	    color: var(--green-ink);
42	    font-family: "Inter Tight", serif;
43	  }
44	  .hero__title .slash {
45	    color: var(--ink-4);
46	    font-weight: 400;
47	    margin: 0 0.1em;
48	  }
49	  .hero__sub {
50	    display: grid;
51	    grid-template-columns: 1.5fr 1fr;
52	    gap: 80px;
53	    align-items: end;
54	    margin-top: 40px;
55	  }
56	  .hero__sub p {
57	    max-width: 56ch;
58	    font-size: clamp(17px, 1.3vw, 20px);
59	    line-height: 1.5;
60	    color: var(--ink-2);
61	    margin: 0;
62	  }
63	  .hero__cta { display: flex; gap: 12px; flex-wrap: wrap; }
64	
65	  .hero__image {
66	    margin-top: 64px;
67	    height: clamp(360px, 52vw, 640px);
68	    position: relative;
69	  }
70	  .hero__image .ph { width: 100%; height: 100%; }
71	
72	  /* stats band */
73	  .stats {
74	    display: grid;
75	    grid-template-columns: repeat(4, 1fr);
76	    border-top: 1px solid var(--rule);
77	    border-bottom: 1px solid var(--rule);
78	  }
79	  .stats .cell {
80	    padding: 36px 24px;
81	    border-right: 1px solid var(--rule);
82	  }
83	  .stats .cell:last-child { border-right: 0; }
84	  .stats .n {
85	    font-family: var(--sans);
86	    font-weight: 500;
87	    font-size: clamp(40px, 4vw, 64px);
88	    letter-spacing: -0.03em;
89	    line-height: 1;
90	  }
91	  .stats .n sup { font-size: 0.5em; color: var(--green-ink); margin-left: 4px; }
92	  .stats .lbl {
93	    margin-top: 14px;
94	    font-family: var(--mono);
95	    font-size: 11px;
96	    letter-spacing: 0.08em;
97	    text-transform: uppercase;
98	    color: var(--ink-3);
99	  }
100	  @media (max-width: 780px) {
101	    .stats { grid-template-columns: 1fr 1fr; }
102	    .stats .cell:nth-child(2) { border-right: 0; }
103	    .stats .cell:nth-child(1),
104	    .stats .cell:nth-child(2) { border-bottom: 1px solid var(--rule); }
105	  }
106	
107	  /* About split */
108	  .about-split {
109	    display: grid;
110	    grid-template-columns: 1fr 1.2fr;
111	    gap: 80px;
112	    align-items: start;
113	  }
114	  .about-split .kicker { margin-bottom: 24px; }
115	  .about-split h2 { margin-bottom: 28px; }
116	  .about-split p + p { margin-top: 16px; }
117	  .about-split__aside {
118	    border-left: 1px solid var(--rule);
119	    padding-left: 40px;
120	    display: grid;
121	    gap: 28px;
122	  }
123	  .factoid { display: grid; gap: 4px; }
124	  .factoid .k {
125	    font-family: var(--mono);
126	    font-size: 11px;
127	    letter-spacing: 0.08em;
128	    text-transform: uppercase;
129	    color: var(--ink-3);
130	  }
131	  .factoid .v { font-size: 18px; letter-spacing: -0.01em; color: var(--ink); font-weight: 500; }
132	  @media (max-width: 900px) {
133	    .about-split { grid-template-columns: 1fr; gap: 40px; }
134	    .about-split__aside { border-left: 0; padding-left: 0; border-top: 1px solid var(--rule); padding-top: 28px; }
135	  }
136	
137	  /* Services list */
138	  .services-list { border-top: 1px solid var(--rule); }
139	  .service-row {
140	    display: grid;
141	    grid-template-columns: 80px 1.6fr 2fr 180px;
142	    gap: 32px;
143	    padding: 32px 0;
144	    border-bottom: 1px solid var(--rule);
145	    align-items: start;
146	    position: relative;
147	    transition: background .2s ease;
148	  }
149	  .service-row:hover { background: rgba(0,0,0,0.02); }
150	  .service-row .idx {
151	    font-family: var(--mono);
152	    font-size: 12px;
153	    color: var(--ink-4);
154	    letter-spacing: 0.06em;
155	    padding-top: 4px;
156	  }
157	  .service-row .title {
158	    font-size: clamp(20px, 1.7vw, 26px);
159	    font-weight: 500;
160	    letter-spacing: -0.015em;
161	    line-height: 1.15;
162	  }
163	  .service-row .desc {
164	    font-size: 15px;
165	    color: var(--ink-2);
166	    line-height: 1.55;
167	    max-width: 52ch;
168	  }
169	  .service-row .tag {
170	    font-family: var(--mono);
171	    font-size: 11px;
172	    text-transform: uppercase;
173	    letter-spacing: 0.08em;
174	    color: var(--ink-3);
175	    padding-top: 6px;
176	  }
177	  .service-row .arrow-cell {
178	    display: flex;
179	    justify-content: flex-end;
180	    padding-top: 6px;
181	  }
182	  @media (max-width: 900px) {
183	    .service-row {
184	      grid-template-columns: 40px 1fr;
185	      gap: 16px 20px;
186	    }
187	    .service-row .desc, .service-row .tag { grid-column: 2; }
188	  }
189	
190	  /* Projects grid */
191	  .projects-head {
192	    display: flex;
193	    justify-content: space-between;
194	    align-items: end;
195	    gap: 24px;
196	    margin-bottom: 48px;
197	  }
198	  .projects-grid {
199	    display: grid;
200	    grid-template-columns: 1.3fr 1fr;
201	    gap: 32px;
202	  }
203	  .project-card { display: block; position: relative; }
204	  .project-card .frame { position: relative; aspect-ratio: 16/11; }
205	  .project-card.tall .frame { aspect-ratio: 4/5; }
206	  .project-card .ph { width: 100%; height: 100%; }
207	  .project-card .meta {
208	    display: flex;
209	    justify-content: space-between;
210	    align-items: baseline;
211	    margin-top: 16px;
212	    gap: 16px;
213	  }
214	  .project-card .title {
215	    font-size: clamp(18px, 1.5vw, 22px);
216	    font-weight: 500;
217	    letter-spacing: -0.01em;
218	  }
219	  .project-card .loc {
220	    font-family: var(--mono);
221	    font-size: 11px;
222	    letter-spacing: 0.08em;
223	    text-transform: uppercase;
224	    color: var(--ink-3);
225	  }
226	  .project-card .cat {
227	    margin-top: 8px;
228	    font-size: 13px;
229	    color: var(--ink-3);
230	  }
231	  .projects-grid--second { grid-template-columns: 1fr 1fr 1fr; }
232	  @media (max-width: 900px) {
233	    .projects-grid, .projects-grid--second { grid-template-columns: 1fr; }
234	  }
235	
236	  /* Team preview */
237	  .team-preview { display: grid; grid-template-columns: 1fr 1fr 1fr 1fr; gap: 24px; }
238	  .member { }
239	  .member .portrait {
240	    aspect-ratio: 3/4;
241	    background:
242	      radial-gradient(circle at 50% 35%, rgba(255,255,255,0.5) 0%, transparent 50%),
243	      linear-gradient(180deg, #DDE1DB 0%, #B6BCB4 100%);
244	    position: relative;
245	    overflow: hidden;
246	    border-radius: 2px;
247	  }
248	  .member .portrait::after {
249	    content: "";
250	    position: absolute;
251	    inset: auto 20% 0 20%;
252	    height: 55%;
253	    background: linear-gradient(180deg, rgba(13,15,14,0.12), rgba(13,15,14,0.35));
254	    border-radius: 50% 50% 0 0 / 40% 40% 0 0;
255	  }
256	  .member .portrait .initials {
257	    position: absolute;
258	    top: 16px; left: 16px;
259	    font-family: var(--mono);
260	    font-size: 11px;
261	    letter-spacing: 0.08em;
262	    color: rgba(13,15,14,0.55);
263	  }
264	  .member .name { margin-top: 14px; font-size: 17px; font-weight: 500; letter-spacing: -0.01em; }
265	  .member .role {
266	    font-family: var(--mono);
267	    font-size: 11px;
268	    letter-spacing: 0.08em;
269	    text-transform: uppercase;
270	    color: var(--ink-3);
271	    margin-top: 4px;
272	  }
273	  @media (max-width: 900px) { .team-preview { grid-template-columns: 1fr 1fr; } }
274	
275	  /* Gallery strip */
276	  .gallery {
277	    display: grid;
278	    grid-template-columns: repeat(12, 1fr);
279	    gap: 12px;
280	    grid-auto-rows: 120px;
281	  }
282	  .gallery .tile { position: relative; }
283	  .gallery .tile .ph { width: 100%; height: 100%; }
284	  .g-a { grid-column: span 5; grid-row: span 3; }
285	  .g-b { grid-column: span 4; grid-row: span 2; }
286	  .g-c { grid-column: span 3; grid-row: span 2; }
287	  .g-d { grid-column: span 4; grid-row: span 2; }
288	  .g-e { grid-column: span 3; grid-row: span 3; }
289	  .g-f { grid-column: span 5; grid-row: span 2; }
290	  @media (max-width: 900px) {
291	    .gallery { grid-template-columns: repeat(2, 1fr); grid-auto-rows: 160px; }
292	    .g-a, .g-b, .g-c, .g-d, .g-e, .g-f { grid-column: span 1; grid-row: span 1; }
293	  }
294	
295	  /* CTA */
296	  .cta-strip {
297	    background: var(--ink);
298	    color: var(--paper);
299	    border-radius: 4px;
300	    padding: clamp(40px, 6vw, 80px);
301	    display: grid;
302	    grid-template-columns: 1.6fr 1fr;
303	    gap: 48px;
304	    align-items: end;
305	    position: relative;
306	    overflow: hidden;
307	  }
308	  .cta-strip::before {
309	    content: "";
310	    position: absolute;
311	    inset: 0;
312	    background:
313	      radial-gradient(circle at 85% 20%, oklch(0.5 0.15 155 / 0.25), transparent 50%),
314	      radial-gradient(circle at 10% 100%, oklch(0.45 0.15 235 / 0.22), transparent 55%);
315	    pointer-events: none;
316	  }
317	  .cta-strip h2 { color: var(--paper); }
318	  .cta-strip .sub { color: #C9CDC9; max-width: 48ch; margin-top: 20px; line-height: 1.5; }
319	  .cta-strip .right { display: grid; gap: 16px; position: relative; z-index: 1; }
320	  .cta-strip .row { display: flex; justify-content: space-between; border-top: 1px solid #2B2F2D; padding-top: 14px; }
321	  .cta-strip .row:first-child { border-top: 0; padding-top: 0; }
322	  .cta-strip .row .k { font-family: var(--mono); font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; color: #9BA19D; }
323	  .cta-strip .row .v { color: #fff; font-size: 14px; font-weight: 500; }
324	  @media (max-width: 900px) { .cta-strip { grid-template-columns: 1fr; } }
325	
326	  /* Section heading */
327	  .sec-head {
328	    display: grid;
329	    grid-template-columns: 200px 1fr 1fr;
330	    gap: 40px;
331	    align-items: baseline;
332	    margin-bottom: 56px;
333	  }
334	  .sec-head .num {
335	    font-family: var(--mono);
336	    font-size: 12px;
337	    color: var(--ink-3);
338	    letter-spacing: 0.08em;
339	  }
340	  .sec-head h2 { max-width: 18ch; }
341	  .sec-head .lede { max-width: 42ch; color: var(--ink-2); font-size: 16px; line-height: 1.55; }
342	  @media (max-width: 900px) {
343	    .sec-head { grid-template-columns: 1fr; gap: 16px; margin-bottom: 32px; }
344	  }
345	
346	  /* Marquee */
347	  .tagline-rule { margin: 0 calc(var(--pad-x) * -1); }
348	</style>
349	</head>
