// Shared nav + footer for all pages.
// Reads data-page attribute from <body> to mark active link.

(function () {
  const NAV_ITEMS = [
    { href: "index.html", key: "home", hr: "Početna", en: "Home" },
    { href: "services.html", key: "services", hr: "Usluge", en: "Services" },
    { href: "projects.html", key: "projects", hr: "Projekti", en: "Projects" },
    { href: "team.html", key: "team", hr: "Tim", en: "Team" },
    { href: "about.html", key: "about", hr: "O nama", en: "About" },
    { href: "contact.html", key: "contact", hr: "Kontakt", en: "Contact" },
  ];

  const STORAGE_KEY = "hidroing-lang";
  function getLang() {
    return localStorage.getItem(STORAGE_KEY) || "hr";
  }
  function setLang(l) {
    localStorage.setItem(STORAGE_KEY, l);
    document.documentElement.setAttribute("data-lang", l);
    // Update any nav labels
    document.querySelectorAll("[data-hr][data-en]").forEach((el) => {
      el.textContent = l === "en" ? el.getAttribute("data-en") : el.getAttribute("data-hr");
    });
    document.querySelectorAll(".lang-toggle button").forEach((b) => {
      b.classList.toggle("active", b.dataset.lang === l);
    });
  }

  function renderNav() {
    const active = document.body.dataset.page || "home";
    const nav = document.createElement("header");
    nav.className = "nav";
    nav.innerHTML = `
      <div class="nav__inner">
        <a href="index.html" class="nav__logo" aria-label="Hidroing">
          <img src="assets/logo.png" alt="Hidroing d.o.o." />
        </a>
        <nav class="nav__links" aria-label="Primary">
          ${NAV_ITEMS.map(
            (i) => `<a href="${i.href}" class="${i.key === active ? "active" : ""}"
                      data-hr="${i.hr}" data-en="${i.en}">${i.hr}</a>`
          ).join("")}
        </nav>
        <div class="nav__right">
          <div class="lang-toggle" role="group" aria-label="Language">
            <button data-lang="hr">HR</button>
            <button data-lang="en">EN</button>
          </div>
        </div>
      </div>
    `;
    document.body.prepend(nav);

    nav.querySelectorAll(".lang-toggle button").forEach((b) => {
      b.addEventListener("click", () => setLang(b.dataset.lang));
    });
  }

  function renderFooter() {
    const f = document.createElement("footer");
    f.className = "footer";
    f.innerHTML = `
      <div class="footer__top">
        <div class="footer__brand">
          <div class="footer__wordmark">hidroing<span class="dot">.</span></div>
          <p data-hr="Projektiranje i inženjering hidrotehničkih građevina. Osijek, Hrvatska."
             data-en="Design and engineering of hydrotechnical facilities. Osijek, Croatia.">
             Projektiranje i inženjering hidrotehničkih građevina. Osijek, Hrvatska.
          </p>
        </div>
        <div>
          <h4 data-hr="Navigacija" data-en="Navigate">Navigacija</h4>
          <ul>
            <li><a href="index.html" data-hr="Početna" data-en="Home">Početna</a></li>
            <li><a href="services.html" data-hr="Usluge" data-en="Services">Usluge</a></li>
            <li><a href="projects.html" data-hr="Projekti" data-en="Projects">Projekti</a></li>
            <li><a href="team.html" data-hr="Tim" data-en="Team">Tim</a></li>
          </ul>
        </div>
        <div>
          <h4 data-hr="Poduzeće" data-en="Company">Poduzeće</h4>
          <ul>
            <li><a href="about.html" data-hr="O nama" data-en="About">O nama</a></li>
            <li><a href="about.html#history" data-hr="Povijest" data-en="History">Povijest</a></li>
            <li><a href="about.html#awards" data-hr="Priznanja" data-en="Awards">Priznanja</a></li>
            <li><a href="about.html#quality" data-hr="Kvaliteta" data-en="Quality">Kvaliteta</a></li>
          </ul>
        </div>
        <div>
          <h4 data-hr="Kontakt" data-en="Contact">Kontakt</h4>
          <ul>
            <li>Tadije Smičiklasa 1<br/>31000 Osijek, HR</li>
            <li><a href="tel:+38531200200">+385 31 200 200</a></li>
            <li><a href="mailto:info@hidroing.hr">info@hidroing.hr</a></li>
          </ul>
        </div>
      </div>
      <div class="footer__bottom">
        <div>© 2026 HIDROING d.o.o.</div>
        <div>OIB 12345678901 · MBS 030012345</div>
        <div data-hr="Izrađeno u Osijeku" data-en="Made in Osijek">Izrađeno u Osijeku</div>
      </div>
    `;
    document.body.appendChild(f);
  }

  function initReveal() {
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            e.target.classList.add("in");
            io.unobserve(e.target);
          }
        });
      },
      { threshold: 0.1 }
    );
    document.querySelectorAll(".reveal").forEach((el) => io.observe(el));
  }

  document.addEventListener("DOMContentLoaded", () => {
    renderNav();
    renderFooter();
    setLang(getLang());
    initReveal();
  });
})();

