/// <reference types="node" />

import path from 'path';
import fs from 'fs';
import chalk from 'chalk';

const ROOT_FOLDER = '.';
const SEARCH_PATTERN = /translations\/.*\.json$/;
const EXCLUDED_FOLDERS = ['node_modules', 'assets', 'playwright', 'stories'];
const TRANSLATIONS_FOLDER = 'translations';

/**
 * Clears all files in a given directory.
 *
 * @param {string} directoryPath - The path of the directory to clear.
 * @throws {Error} If there is an error reading the directory or removing a file.
 *
 * @example
 * clearDirectory('./path/to/directory');
 */
function clearDirectory(directoryPath) {
    if (!fs.existsSync(directoryPath)) {
        console.log(chalk.red('- Directory does not exist:'), directoryPath);
        return;
    }

    console.log(
        chalk.blue('Removing old translations in directory:'),
        directoryPath,
    );

    const files = fs.readdirSync(directoryPath);
    for (const file of files) {
        const filePath = path.join(directoryPath, file);

        const stats = fs.statSync(filePath);
        if (stats.isFile()) {
            fs.unlinkSync(filePath);
            console.log(`Removed file: ${filePath}`);
        }
    }
}

/**
 *
 * @param {string} startDir - Path from which script will look for translations recursively
 * @param {RegExp} regexFilter - Regex filter used to match files
 * @param {string[]} excludedFolders - A list of folders which script should ignore
 * @param {function} callback - Callback function called when translation file is found
 */
function findTranslations(startDir, regexFilter, excludedFolders, callback) {
    if (startDir === ROOT_FOLDER) {
        console.log(
            chalk.blue('Compiling new translations:'),
            TRANSLATIONS_FOLDER,
        );
    }

    console.log(
        chalk.blue('- Finding translation files in directory:'),
        startDir,
    );

    if (!fs.existsSync(startDir)) {
        console.log(chalk.red('- Directory does not exist:'), startDir);
        return;
    }

    const files = fs.readdirSync(startDir);
    for (var i = 0; i < files.length; i++) {
        var filename = path.join(startDir, files[i]);
        var stat = fs.lstatSync(filename);

        if (stat.isDirectory()) {
            if (
                excludedFolders.includes(filename) ||
                filename.startsWith('.')
            ) {
                console.log(
                    chalk.blue('- Excluded folder from search:'),
                    chalk.yellow(filename),
                );
                continue;
            }

            findTranslations(filename, regexFilter, excludedFolders, callback);
        } else if (regexFilter.test(filename)) {
            callback(filename);
        }
    }
}

/**
 *
 * @param {string} filePath - Path to the translation file which needs to be compiled
 */
function appendTranslationFile(filePath) {
    console.log(
        chalk.green('- Translation file found:'),
        chalk.yellow(filePath),
    );

    const translationFile = JSON.parse(fs.readFileSync(filePath));
    const locale = filePath.split('/').pop().replace('.json', '');

    if (!fs.existsSync(TRANSLATIONS_FOLDER)) {
        fs.mkdirSync(TRANSLATIONS_FOLDER, { recursive: true });
    }

    const resultTranslationFilePath = `${TRANSLATIONS_FOLDER}/${locale}.json`;
    if (!fs.existsSync(resultTranslationFilePath)) {
        fs.writeFileSync(resultTranslationFilePath, JSON.stringify({}), {
            flag: 'w',
        });
    }

    const resultTranslationFile = JSON.parse(
        fs.readFileSync(resultTranslationFilePath),
    );

    fs.writeFileSync(
        resultTranslationFilePath,
        JSON.stringify({
            ...resultTranslationFile,
            ...translationFile,
        }),
    );
}

clearDirectory(TRANSLATIONS_FOLDER);
findTranslations(
    ROOT_FOLDER,
    SEARCH_PATTERN,
    EXCLUDED_FOLDERS,
    appendTranslationFile,
);

